const advForeignCheckpoint = "a1b2c3d4e5f6"

// advCheckpointStored reports whether a committed checkpoint exists locally in
// either layout: a per-checkpoint ref (git-refs backend, and where ULID-format
// IDs land regardless of backend) or a summary on the v1 metadata branch.
func advCheckpointStored(env *TestEnv, checkpointID string) bool {
	env.T.Helper()
	cmd := exec.CommandContext(env.T.Context(), "git", "rev-parse", "--verify", "-q", checkpointRefName(checkpointID))
	cmd.Dir = env.RepoDir
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.Output(); err == nil && strings.TrimSpace(string(out)) != "" {
		return true
	}
	_, found := env.ReadFileFromBranch(paths.MetadataBranchName, CheckpointSummaryPath(checkpointID))
	return found
}

// advCommit runs the real prepare-commit-msg hook (as a human at a TTY) with
// the given source, then edits the message the way the user would before git
// records it: `#` lines are dropped (git's default cleanup) and any
// Entire-Checkpoint line for which keep returns false is removed. Removing the
// trailer prepare just stamped models both answering "n" at the -m prompt and
// deleting the stamped line in the editor. Returns the message as prepare left
// it and the message committed.
func advCommit(env *TestEnv, message, source string, keep func(checkpointID string) bool, files ...string) (string, string) {
	env.T.Helper()
	for _, f := range files {
		env.GitAdd(f)
	}
	_, prepared := runPrepareCommitMsg(env, message, source)

	var kept []string
	for _, line := range strings.Split(prepared, "\n") {
		if strings.HasPrefix(line, "#") {
			continue
		}
		if cpID, ok := strings.CutPrefix(strings.TrimSpace(line), trailers.CheckpointTrailerKey+": "); ok && !keep(cpID) {
			continue
		}
		kept = append(kept, line)
	}
	final := strings.TrimRight(strings.Join(kept, "\n"), "\n") + "\n"
	if strings.TrimSpace(strings.SplitN(final, "\n", 2)[0]) == "" {
		final = "typed in editor" + final // the subject the user types
	}
	commitWithPostCommit(env, final)
	return prepared, final
}

// commitWithPostCommit records the staged changes with message, as git does
// once prepare-commit-msg and the editor are done, then runs post-commit.
func commitWithPostCommit(env *TestEnv, message string) {
	env.T.Helper()
	recordWithPostCommit(env, message, false)
}

// amendWithPostCommit is commitWithPostCommit for `git commit --amend`.
func amendWithPostCommit(env *TestEnv, message string) {
	env.T.Helper()
	recordWithPostCommit(env, message, true)
}

func recordWithPostCommit(env *TestEnv, message string, amend bool) {
	env.T.Helper()
	repo, err := gitrepo.OpenPath(env.RepoDir)
	require.NoError(env.T, err)
	defer repo.Close()
	wt, err := repo.Worktree()
func authorityAgentTurn(env *TestEnv, path, content string) {
	env.T.Helper()
	sess := env.NewSession()
	require.NoError(env.T, env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(sess.ID, "change "+path, sess.TranscriptPath))
	env.WriteFile(path, content)
	sess.CreateTranscript("change "+path, []FileChange{{Path: path, Content: content}})
	require.NoError(env.T, env.SimulateStop(sess.ID, sess.TranscriptPath))
}

// requireFreshFinalTrailer returns the checkpoint the commit's final trailer
// block names, requiring it to differ from the one its body mentions.
func requireFreshFinalTrailer(t *testing.T, message, mentioned string) string {
	t.Helper()
	stamped := trailers.ParseAllCheckpointsFromFinalTrailerBlock(message, "")
	require.Len(t, stamped, 1, "prepare-commit-msg must stamp a trailer in the final block: %q", message)
	require.NotEqual(t, mentioned, stamped[0].String(), "the stamped trailer must not reuse the body's ID: %q", message)
	return stamped[0].String()
}
